-- Resources content for the table session and the consent wording (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- The prefix continues the sequence past 20261111140000; see 20261103120000's header on why a prefix is a sequence number.
--
-- What changed for a reader: a Consent wording page (a coordinator adds numbered versions), and the Portal's table side of a session: the
-- single-use link, the agreement recorded with the wording version shown, and recording in segments. The earlier Campaigns, events and
-- table cards guide is updated in place (its last section said recording was still to come); a guide an editor has changed since is
-- flagged for review and not overwritten.
--
-- Station-neutral on purpose: a guide is kept data, and the fresh-install check fails on any kept guide that names a station.

select private.rc_release_guide(
  p_slug => 'audience-listening-campaigns-events-and-table-cards',
  p_tool_key => 'audience-listening',
  p_title => 'Campaigns, events and table cards',
  p_summary => 'Set up a season of listening, schedule events inside it, get a public event listed, and print the cards for its tables.',
  p_screen_keys => array['audience-listening.campaigns', 'audience-listening.campaign', 'audience-listening.events', 'audience-listening.event'],
  p_sort_order => 50,
  p_version_note => 'The table side of a session is in the Portal',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"campaign","marks":[{"type":"bold"}]},{"type":"text","text":" is a season of listening: one question, the prompts a table is walked through, a list of tags, and the dates it runs. An "},{"type":"text","text":"event","marks":[{"type":"bold"}]},{"type":"text","text":" is a session in a place at a time inside that season, and a "},{"type":"text","text":"table","marks":[{"type":"bold"}]},{"type":"text","text":" is one conversation at it. A kitchen table is an event with one table. Campaigns and Events sit beside Queries in the section's navigation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Campaigns"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose Campaigns, then New campaign. Give it a title, the question it asks, an introduction for the website, and the dates it opens and closes. It starts as a draft and nothing is public."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prompts and tags","marks":[{"type":"bold"}]},{"type":"text","text":" holds what a table is asked, in order, and the words a facilitator picks from when they mark a line as what mattered. Each prompt can carry a hint for the facilitator and a suggested time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the campaign once it has at least one prompt. Closing it also closes the query linked to it under Settings, so a question is not still taking answers after the season is over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a draft with no events can be deleted. A campaign that ran is closed and then archived, so what it heard stays on the record."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Add an event from its campaign's Events tab. Its start has to fall inside the campaign's dates; the Portal refuses it otherwise. Times are the station's local time."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"private","marks":[{"type":"bold"}]},{"type":"text","text":" event is never listed. The organizer shares it themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"public","marks":[{"type":"bold"}]},{"type":"text","text":" event needs an address and a number of seats, and can be listed on the website only after a coordinator approves it. Anyone can ask for a review. A coordinator approves it after ticking each item on the checklist (a public place, an identified organizer with a verified email, a date inside the campaign, accessibility details, not a fundraiser or campaign event, and the consent reading acknowledged), or declines it with a reason the organizer is told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If anyone other than a coordinator changes what the public sees on a listed event (its title, time, place, address or seats), it goes back to review. Making an event private takes it off the website at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approving, declining and taking an event off the website are recorded with who did them. The Events page can show only those waiting for review, and the count appears beside Events in the navigation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tables and cards"}]},{"type":"paragraph","content":[{"type":"text","text":"On an event, add the tables it needs. "},{"type":"text","text":"Make new links and cards for every table","marks":[{"type":"bold"}]},{"type":"text","text":" gives each table a single-use link and draws a card for it with a QR code, to print at 7 by 5 inches, one to a page."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A link is shown once, on that page. The Portal keeps only a scrambled copy, so a card cannot be reprinted later. To get a card back, make a new link."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new link replaces the old one. A card printed earlier, and any phone using it, stops working. If one phone is lost or cannot scan, make a new link for that table alone and read it out or show it to the person."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Making links needs the website's address to be set on the server. If it is not, the page says so instead of printing a card that goes nowhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that has not started can be removed. One that has been agreed to or recorded is kept."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Seats"}]},{"type":"paragraph","content":[{"type":"text","text":"A public event shows the seats people have saved, each with a name and an email given for that event only. Remove one to free the seat and delete the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The table side of a session (the agreement, the recording and the segments) is in the Portal and shows on each table, but the website pages that a card opens are still to come. Until they are, a printed card does not open anything, so do not print cards for a real session yet. Naming speakers, highlights, contact cards, the room console and the review of a conversation come after."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing on these pages is public until you say so, and a public event is never listed without a coordinator."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-consent-wording-and-tables',
  p_tool_key => 'audience-listening',
  p_title => 'Consent wording and what happens at a table',
  p_summary => 'Write the words a facilitator reads aloud, and see how a table agrees, records and finishes.',
  p_screen_keys => array['audience-listening.consent'],
  p_sort_order => 60,
  p_version_note => 'Consent wording and tables',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before a table records, its facilitator reads a short agreement aloud and taps to say the whole table agrees. This page holds those words. Open it from "},{"type":"text","text":"Consent wording","marks":[{"type":"bold"}]},{"type":"text","text":" on the Campaigns page."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The wording"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The words are kept as numbered versions. A version is never edited: a change is a new version, so each table's agreement points at the exact words its facilitator read."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a coordinator can add a version. Settle the wording with the University's counsel and the records officer before the first real session."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"With no wording saved, no table can open, because its page would have nothing to read aloud. The event page says so."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens at a table"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card's QR code opens the table's single-use link. Opening it starts a session for that phone. A second phone using the same link is turned away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The facilitator reads the wording and taps to agree. The Portal records when, the wording version they were shown, and their first name if they gave one. Nothing records before this."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The phone records in segments of at most five minutes and uploads each as it goes, so a dropped connection picks up where it left off. When the table ends, the conversation is complete once every segment has arrived."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the event page each table shows when it agreed, to which version, who facilitated, whether it asked for a hand, and how much has been recorded. If a phone is lost, make a new link for that table: it ends the old session."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The website pages a card opens are still to come, so none of this works from a phone yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Naming speakers, marking highlights, leaving a contact card, the room console and the review of a conversation are not here yet."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-11-audience-listening-table-sessions',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-11',
  p_title => 'Consent wording and table recording arrive in Audience Listening',
  p_guide_slugs => array['audience-listening-consent-wording-and-tables'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Audience Listening has a new Consent wording page, reached from Campaigns. A coordinator writes the words a facilitator reads aloud before a table records, as numbered versions that are never edited. The Portal now carries the table side of a session: opening a table's single-use link, recording the table's agreement with the wording version shown, and receiving the recording in segments that resume after a dropped connection. Each table on an event shows when it agreed, to which version, its facilitator and how much has been recorded. The website pages that open a card are not built yet, so a table cannot be used from a phone."}]}]}$body$
);
